mapper.insert:
INSERT INTO task_log (task_id, workspace_id, actor_id, action, detail)
SELECT t.id, t.workspace_id, #{actorId}, 'update', #{detail}
FROM task t
WHERE t.workspace_id = #{workspaceId} AND t.req_id = #{reqId}

mapper.select:
SELECT l.id, l.task_id, l.workspace_id, l.actor_id, l.action, l.detail, l.from_column, l.to_column, l.created_at, u.display_name AS actor_name, t.title AS task_title FROM task_log l LEFT JOIN app_user u ON u.id = l.actor_id LEFT JOIN task t ON t.id = l.task_id AND t.workspace_id = l.workspace_id WHERE l.workspace_id = #{workspaceId}
AND l.task_id <> 'CFG'
AND (l.task_id = 'CFG' OR NOT EXISTS ( SELECT 1 FROM task t2 JOIN project_member pm ON pm.workspace_id = t2.workspace_id AND pm.project_id = t2.req_id AND pm.user_id = #{viewerId} WHERE t2.id = l.task_id AND t2.workspace_id = l.workspace_id AND pm.access = 'none'))
ORDER BY l.id DESC LIMIT #{limit}

SELECT DISTINCT l.task_id
FROM task_log l
WHERE l.workspace_id = #{workspaceId}
  AND l.task_id <> 'CFG'
  AND l.created_at >= #{from}
  AND l.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
